{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, which shares the methylsulfonylphenyl, chloroaromatic, and heterobiaryl features of the query, has a measured absolute bioavailability of 31.8% in healthy subjects after a 150 mg oral dose, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Rofecoxib, a methylsulfonylphenyl-containing lipophilic drug, has a mean oral bioavailability of approximately 93% in healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Valdecoxib, a structurally related sulfonyl-containing heteroaryl drug, has an absolute bioavailability of 83% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Esaxerenone, another sulfonyl-containing lipophilic drug, shows an absolute bioavailability of 89.0% in the fasting state in healthy subjects, supporting high oral bioavailability for the query under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "5-Hydroxyrofecoxib, a polar hydroxylated metabolite of rofecoxib, has low oral bioavailability (14.0%), but this contradictory evidence transfers weakly because the query lacks the hydroxyl/lactone polarity and is more similar to the highly bioavailable parent sulfone drugs.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct human absolute bioavailability measurements in structurally related methylsulfonylphenyl/heterobiaryl drugs (vismodegib 31.8%, rofecoxib ~93%, valdecoxib 83%, esaxerenone ~90%) consistently support F ≥ 20%. The only low-F analogue is a polar hydroxy metabolite with weak transferability. The mixed physicochemical prior is outweighed by the convergent experimental evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data are available for the query molecule.",
    "Morgan similarities to the evidence molecules are low to moderate, limiting quantitative transferability.",
    "Solubility and metabolic stability of the query are not directly measured.",
    "Potential food effects or formulation-dependent bioavailability were not assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

